'use strict';

// MODULES //

import isnan from '@stdlib/math-base-assert-is-nan';
import incrwmean from '@stdlib/stats-incr-wmean';


// MAIN //

/**
* Returns an accumulator function which incrementally computes a weighted arithmetic mean, ignoring `NaN` values.
*
* @returns {Function} accumulator function
*
* @example
* var accumulator = incrnanwmean();
*
* var mu = accumulator();
* // returns null
*
* mu = accumulator( 2.0, 1.0 );
* // returns 2.0
*
* mu = accumulator( NaN, 1.0 );
* // returns 2.0
*
* mu = accumulator( 2.0, 0.5 );
* // returns 2.0
*
* mu = accumulator( 3.0, 1.5 );
* // returns 2.5
*
* mu = accumulator();
* // returns 2.5
*/
function incrnanwmean() {
	var wmean = incrwmean();
	return accumulator;

	/**
	* If provided arguments, the accumulator function returns an updated weighted mean. If not provided arguments, the accumulator function returns the current weighted mean.
	*
	* @private
	* @param {number} [x] - value
	* @param {number} [w] - weight
	* @returns {(number|null)} weighted mean or null
	*/
	function accumulator( x, w ) {
		if ( arguments.length === 0 || isnan( x ) || isnan( w ) ) {
			return wmean();
		}
		return wmean( x, w );
	}
}


// EXPORTS //

export default incrnanwmean;
